20	template <typename DstTileData, typename SrcTileData, STPhase Phase = STPhase::Unspecified>
21	PTO_INTERNAL void TMOV_IMPL(DstTileData& dst, SrcTileData& src)
22	{
23	    (void)Phase;
24	    if constexpr (is_conv_tile_v<SrcTileData>) {
25	        TEXTRACT(dst, src, 0, 0);
26	    } else {
27	        assert(src.GetValidRow() == dst.GetValidRow() && src.GetValidCol() == dst.GetValidCol());
28	        for (size_t c = 0; c < src.GetValidCol(); c++) {
29	            for (size_t r = 0; r < src.GetValidRow(); r++) {
30	                dst.SetElement(r, c, src.GetElement(r, c));
31	            }
32	        }
33	    }
34	}
35	
36	template <typename DstTileData, typename SrcTileData, ReluPreMode reluMode, STPhase Phase = STPhase::Unspecified>
37	PTO_INTERNAL void TMOV_IMPL(DstTileData& dst, SrcTileData& src)
38	{
39	    (void)Phase;
40	    TMOV_IMPL(dst, src);
41	    if constexpr (reluMode == ReluPreMode::NormalRelu) {
42	        const std::size_t rows = static_cast<std::size_t>(dst.GetValidRow());
43	        const std::size_t cols = static_cast<std::size_t>(dst.GetValidCol());
44	        for (std::size_t r = 0; r < rows; ++r) {
45	            for (std::size_t c = 0; c < cols; ++c) {
46	                auto& v = dst.data()[GetTileElementOffset<DstTileData>(r, c)];
47	                if (v < static_cast<typename DstTileData::DType>(0)) {
48	                    v = static_cast<typename DstTileData::DType>(0);
49	                }
50	            }
51	        }
52	    }
53	}
