10	#ifndef TTRANS_HPP
11	#define TTRANS_HPP
12	
13	#include <pto/common/pto_tile.hpp>
14	#include "pto/cpu/tile_offsets.hpp"
15	#include <type_traits>
16	#include <cstdint>
17	
18	namespace pto {
19	
20	template <typename T>
21	struct is_one_of_mx_types
22	    : std::disjunction<
23	          std::is_same<T, float4_e2m1x2_t>, std::is_same<T, float4_e1m2x2_t>, std::is_same<T, float8_e8m0_t>,
24	          std::is_same<T, float8_e4m3_t>, std::is_same<T, float8_e5m2_t> > {};
25	
26	template <typename T>
27	inline constexpr bool is_one_of_mx_types_v = is_one_of_mx_types<T>::value;
28	
29	template <typename T>
30	inline constexpr int GetTypeSize()
31	{
32	    if constexpr (is_one_of_mx_types_v<T>)
33	        return 1;
34	    else
35	        return static_cast<int>(sizeof(T));
36	}
37	
38	template <typename DstTileData, typename SrcTileData>
39	inline void CheckValidConvShape(DstTileData& dst, SrcTileData& src)
40	{
41	    using T = typename DstTileData::DType;
42	    constexpr int64_t C0 = 32 / GetTypeSize<T>() * (IsTwinType<T>() ? 2 : 1);
43	
44	    constexpr Layout src_layout = SrcTileData::layout;
45	    constexpr Layout dst_layout = DstTileData::layout;
46	    constexpr int DIM_0 = pto::GlobalTensorDim::DIM_0;
47	    constexpr int DIM_1 = pto::GlobalTensorDim::DIM_1;
48	    constexpr int DIM_2 = pto::GlobalTensorDim::DIM_2;
49	    constexpr int DIM_3 = pto::GlobalTensorDim::DIM_3;
50	    constexpr int DIM_4 = pto::GlobalTensorDim::DIM_4;
51	    constexpr int DIM_5 = 5;
52	
53	    if constexpr (src_layout == Layout::NCHW && dst_layout == Layout::NC1HWC0) {
54	        // NCHW (N, C, H, W) -> NC1HWC0 (N, C1, H, W, C0)
55	        // C1 = ceil(C / C0)
56	        assert(
57	            dst.GetShape(DIM_0) == src.GetShape(DIM_0) &&                 // N
58	            dst.GetShape(DIM_1) == (src.GetShape(DIM_1) + C0 - 1) / C0 && // C1
59	            dst.GetShape(DIM_2) == src.GetShape(DIM_2) &&                 // H
60	            dst.GetShape(DIM_3) == src.GetShape(DIM_3) &&                 // W
61	            dst.GetShape(DIM_4) == C0 &&                                  // C0
62	            "Shape mismatch: NCHW to NC1HWC0");
63	    } else if constexpr (src_layout == Layout::NC1HWC0 && dst_layout == Layout::NCHW) {
64	        // NCHW (N, C, H, W) -> NC1HWC0 (N, C1, H, W, C0)
65	        // C1 = ceil(C / C0)
66	        assert(
67	            dst.GetShape(DIM_0) == src.GetShape(DIM_0) &&      // N
68	            dst.GetShape(DIM_1) == src.GetShape(DIM_1) * C0 && // C1
69	            dst.GetShape(DIM_2) == src.GetShape(DIM_2) &&      // H
70	            dst.GetShape(DIM_3) == src.GetShape(DIM_3) &&      // W
71	            src.GetShape(DIM_4) == C0 && "Shape mismatch: NC1HWC0 to NCHW");
72	    } else if constexpr (src_layout == Layout::NC1HWC0 && dst_layout == Layout::FRACTAL_Z) {
73	        // NC1HWC0 (N, C1, H, W, C0) -> C1HWN1N0C0 (C1, H, W, N1, N0, C0)
74	        // N = N1 * N0
75	        assert(
76	            dst.GetShape(DIM_0) == src.GetShape(DIM_1) * src.GetShape(DIM_2) * src.GetShape(DIM_3) && // C1*H*W
77	            dst.GetShape(DIM_1) * dst.GetShape(DIM_2) >= src.GetShape(DIM_0) &&                       // N1*N0 = N
78	            dst.GetShape(DIM_3) == src.GetShape(DIM_4) &&                                             // C0
79	            "Shape mismatch: NC1HWC0 to FRACTAL_Z");
80	    } else if constexpr (src_layout == Layout::GNCHW && dst_layout == Layout::GNC1HWC0) {
81	        // GNCHW (G, N, C, H, W) -> GNC1HWC0 (G, N, C1, H, W, C0)
82	        assert(
83	            dst.GetShape(DIM_0) == src.GetShape(DIM_0) &&                      // G
84	            dst.GetShape(DIM_1) == src.GetShape(DIM_1) &&                      // N
85	            dst.GetShape(DIM_3) == src.GetShape(DIM_3) &&                      // H
86	            dst.GetShape(DIM_4) == src.GetShape(DIM_4) &&                      // W
87	            dst.GetShape(DIM_2) == (src.GetShape(DIM_2) + C0 - 1) / C0 &&      // C1
88	            dst.GetShape(DIM_5) == C0 && "Shape mismatch: GNCHW to GNC1HWC0"); // C0
89	    } else if constexpr (src_layout == Layout::GNC1HWC0 && dst_layout == Layout::FRACTAL_Z) {
90	        // GNC1HWC0 (G, N, C1, H, W, C0) -> C1HWGN1N0C0 (C1, H, W, G, N1, N0, C0)
91	        // Note: Assuming Dst shape maps dimensions G*C1*H*W as outer dimension
92	        assert(
93	            dst.GetShape(DIM_0) ==
94	                src.GetShape(DIM_0) * src.GetShape(DIM_2) * src.GetShape(DIM_3) * src.GetShape(DIM_4) && // C1, H, W, G
95	            dst.GetShape(DIM_1) == (src.GetShape(DIM_1) + dst.GetShape(DIM_2) - 1) / dst.GetShape(DIM_2) && // N1*N0
96	            dst.GetShape(DIM_3) == src.GetShape(DIM_5) &&                                                   // C0
97	            "Shape mismatch: GNC1HWC0 to FRACTAL_Z");
98	    } else if constexpr (src_layout == Layout::NCDHW && dst_layout == Layout::FRACTAL_Z_3D) {
99	        // NCDHW (N, C, D, H, W) -> FRACTAL_Z_3D (D, C1, H, W, N1, N0, C0)
100	        // Note: D, C1, H, W are merged into DIM 0 for dst.
101	        size_t dstC1 = dst.GetShape(DIM_0) / (src.GetShape(DIM_2) * src.GetShape(DIM_3) * src.GetShape(DIM_4));
102	        assert(
103	            dstC1 == (src.GetShape(DIM_1) + C0 - 1) / C0 &&
104	            dst.GetShape(DIM_1) == (src.GetShape(DIM_0) + dst.GetShape(DIM_2) - 1) / dst.GetShape(DIM_2) && // N1*N0
105	            dst.GetShape(DIM_3) == C0 &&                                                                    // C0
106	            "Shape mismatch: NCDHW to FRACTAL_Z_3D");
107	    }
108	}
109	
110	template <typename DstTileData, typename SrcTileData, bool reverse = false>
111	inline void TTRANS_GNCHW2NC1HWC0_Impl(
112	    DstTileData& dst, SrcTileData& src, int64_t G, int64_t N, int64_t C, int64_t H, int64_t W)
113	{
114	    using SrcDType = typename SrcTileData::DType;
115	    using DstDType = typename DstTileData::DType;
116	
117	    auto* src_ptr = reinterpret_cast<SrcDType*>(src.data());
118	    auto* dst_ptr = reinterpret_cast<DstDType*>(dst.data());
119	
120	    constexpr int64_t C0 = (32 / GetTypeSize<SrcDType>()) * (IsTwinType<DstDType>() ? 2 : 1);
121	    int64_t C1 = (C + C0 - 1) / C0;
122	    const size_t HW = H * W;
123	    const size_t CHW = C * HW;
124	    const size_t C1HW_C0 = C1 * HW * C0;
125	
126	    for (int64_t g = 0; g < G; ++g) {
127	        size_t gOffset_src = g * (N * CHW);
128	        size_t gOffset_dst = g * (N * C1HW_C0);
129	
130	        for (int64_t n = 0; n < N; ++n) {
131	            size_t nOffset_src = n * CHW;
132	            size_t nOffset_dst = n * C1HW_C0;
133	
134	            for (int64_t c = 0; c < C; ++c) {
135	                size_t r = c / C0;
136	                size_t cl = c % C0;
137	
138	                size_t cOffset_src = c * HW;
139	                size_t cOffset_dst = (r * HW * C0) + cl;
140	
141	                for (int64_t h = 0; h < H; ++h) {
142	                    size_t hOffset_src = h * W;
143	                    size_t hOffset_dst = h * (W * C0);
144	
145	                    size_t base_src = gOffset_src + nOffset_src + cOffset_src + hOffset_src;
146	                    size_t base_dst = gOffset_dst + nOffset_dst + cOffset_dst + hOffset_dst;
147	
148	                    for (int64_t w = 0; w < W; ++w) {
149	                        if constexpr (reverse) {
150	                            SetProperDataPart(src_ptr, base_src + w, GetProperDataPart(dst_ptr, base_dst + w * C0));
151	                        } else {
152	                            SetProperDataPart(dst_ptr, base_dst + w * C0, GetProperDataPart(src_ptr, base_src + w));
153	                        }
154	                    }
155	                }
156	            }
157	        }
158	    }
159	}
160	
161	template <typename DstTileData, typename SrcTileData>
162	inline void TTRANS_NCHW2NC1HWC0(DstTileData& dst, SrcTileData& src)
163	{
164	    int64_t G = 1; // 4D layout has 1 implicit group
165	    int64_t N = src.GetShape(0);
166	    int64_t C = src.GetShape(1);
167	    int64_t H = src.GetShape(2);
168	    int64_t W = src.GetShape(3);
169	
170	    TTRANS_GNCHW2NC1HWC0_Impl(dst, src, G, N, C, H, W);
171	}
172	
173	template <typename DstTileData, typename SrcTileData>
174	inline void TTRANS_NC1HWC02NCHW(DstTileData& dst, SrcTileData& src)
175	{
176	    int64_t G = 1; // 4D layout has 1 implicit group
177	    int64_t N = dst.GetShape(0);
178	    int64_t C = dst.GetShape(1);
179	    int64_t H = dst.GetShape(2);
180	    int64_t W = dst.GetShape(3);
181	
182	    TTRANS_GNCHW2NC1HWC0_Impl<SrcTileData, DstTileData, true>(src, dst, G, N, C, H, W);
183	}
184	
185	template <typename DstTileData, typename SrcTileData>
186	inline void TTRANS_GNCHW2NC1HWC0(DstTileData& dst, SrcTileData& src)
187	{
188	    int64_t G = src.GetShape(0);
189	    int64_t N = src.GetShape(1);
190	    int64_t C = src.GetShape(2);
191	    int64_t H = src.GetShape(3);
192	    int64_t W = src.GetShape(4);
193	
194	    TTRANS_GNCHW2NC1HWC0_Impl(dst, src, G, N, C, H, W);
195	}
196	
197	template <typename DstTileData, typename SrcTileData>
198	inline void TTRANS_GNC1HWC02C1HWN1N0C0_Impl(
199	    DstTileData& dst, SrcTileData& src, int64_t G, int64_t N, int64_t C1, int64_t H, int64_t W)
200	{
201	    using SrcDType = typename SrcTileData::DType;
202	    using DstDType = typename DstTileData::DType;
203	
204	    auto* src_ptr = reinterpret_cast<SrcDType*>(src.data());
205	    auto* dst_ptr = reinterpret_cast<DstDType*>(dst.data());
206	
207	    int64_t N1 = dst.GetShape(1);
208	    int64_t N0 = dst.GetShape(2);
209	    int64_t C0 = dst.GetShape(3);
210	
211	    assert(N0 > 0 && "N0 must be greater than 0!");
212	
213	    const size_t HW = H * W;
214	    const size_t C1HW = C1 * HW;
215	    const size_t C0_N0 = C0 * N0;
216	    const size_t C0_N0_N1 = C0_N0 * N1;
217	
218	    for (int64_t g = 0; g < G; ++g) {
219	        // Source offset for group g
220	        const size_t g_src_offset = g * N * C1HW * C0;
221	
222	        for (int64_t n = 0; n < N; ++n) {
223	            const size_t n1 = n / N0;
224	            const size_t n0 = n % N0;
225	
226	            const size_t n_src_offset = g_src_offset + (n * C1HW * C0);
227	            const size_t dst_n_base = (n0 * C0) + (n1 * C0_N0);
228	
229	            for (int64_t c1 = 0; c1 < C1; ++c1) {
230	                const size_t c1_src_offset = n_src_offset + (c1 * HW * C0);
231	
232	                // Destination block base for (g, c1)
233	                const size_t g_c1_dst_base = (g * C1HW + c1 * HW) * C0_N0_N1;
234	
235	                for (int64_t h = 0; h < H; ++h) {
236	                    const size_t h_src_offset = c1_src_offset + (h * W * C0);
237	                    const size_t h_dst_offset = h * W * C0_N0_N1;
238	
239	                    for (int64_t w = 0; w < W; ++w) {
240	                        size_t src_base = h_src_offset + (w * C0);
241	                        size_t dst_base = dst_n_base + g_c1_dst_base + h_dst_offset + (w * C0_N0_N1);
242	
243	                        // Continuous block copy
244	                        for (size_t c0 = 0; c0 < C0; ++c0) {
245	                            SetProperDataPart(dst_ptr, dst_base + c0, GetProperDataPart(src_ptr, src_base + c0));
246	                        }
247	                    }
248	                }
249	            }
250	        }
251	    }
252	}
253	
254	template <typename DstTileData, typename SrcTileData>
255	inline void TTRANS_NC1HWC02C1HWN1N0C0(DstTileData& dst, SrcTileData& src)
256	{
257	    int64_t G = 1; // 4D layout implies 1 implicit group
258	    int64_t N = src.GetShape(0);
259	    int64_t C1 = src.GetShape(1);
260	    int64_t H = src.GetShape(2);
261	    int64_t W = src.GetShape(3);
262	
263	    TTRANS_GNC1HWC02C1HWN1N0C0_Impl(dst, src, G, N, C1, H, W);
264	}
265	
266	template <typename DstTileData, typename SrcTileData>
267	inline void TTRANS_GNC1HWC02C1HWN1N0C0(DstTileData& dst, SrcTileData& src)
268	{
269	    int64_t G = src.GetShape(0);
270	    int64_t N = src.GetShape(1);
271	    int64_t C1 = src.GetShape(2);
272	    int64_t H = src.GetShape(3);
273	    int64_t W = src.GetShape(4);
274	
275	    TTRANS_GNC1HWC02C1HWN1N0C0_Impl(dst, src, G, N, C1, H, W);
276	}
277	
278	template <typename DstTileData, typename SrcTileData>
279	inline void TTRANS_NCDHW2DC1HWN1N0C0(DstTileData& dst, SrcTileData& src)
280	{
281	    using SrcDType = typename SrcTileData::DType;
282	    using DstDType = typename DstTileData::DType;
283	
284	    const auto* src_ptr = reinterpret_cast<const SrcDType*>(src.data());
285	    auto* dst_ptr = reinterpret_cast<DstDType*>(dst.data());
286	
287	    // Shape extraction
288	    const int64_t N = src.GetShape(0);
289	    const int64_t C = src.GetShape(1);
290	    const int64_t D = src.GetShape(2);
291	    const int64_t H = src.GetShape(3);
292	    const int64_t W = src.GetShape(4);
293	
294	    const int64_t C0 = dst.GetShape(3); // Assuming index 3 is C0
295	    const int64_t N0 = dst.GetShape(2);
296	    const int64_t N1 = dst.GetShape(1);
297	    const int64_t C1 = (C + C0 - 1) / C0;
298	
299	    const size_t HW = H * W;
300	    const size_t DHW = D * HW;
301	    const size_t CDHW = C * DHW;
302	    const size_t C0_N0 = C0 * N0;
303	    const size_t C0_N0_N1 = C0_N0 * N1;
304	    const size_t C1HW = C1 * H * W;
305	
306	    for (int64_t n = 0; n < N; ++n) {
307	        const size_t n1 = n / N0;
308	        const size_t n0 = n % N0;
309	        const size_t dst_base_n = n1 * C0_N0 + n0 * C0;
310	        const size_t src_base_n = n * CDHW;
311	        for (int64_t c = 0; c < C; ++c) {
312	            const size_t c1 = c / C0;
313	            const size_t c0 = c % C0;
314	            const size_t src_base_c = src_base_n + c * DHW;
315	            const size_t dst_base_c1 = c1 * HW;
316	            for (int64_t d = 0; d < D; ++d) {
317	                const size_t src_base_d = src_base_c + d * HW;
318	                const size_t dst_base_d = d * C1HW + dst_base_c1;
319	                for (int64_t h = 0; h < H; ++h) {
320	                    for (int64_t w = 0; w < W; ++w) {
321	                        const size_t base_w = h * W + w;
322	                        // Offset in NCDHW source
323	                        size_t src_offset = src_base_d + base_w;
324	
325	                        // Base for fractal block
326	                        size_t dst_base = (dst_base_d + base_w) * C0_N0_N1 + dst_base_n + c0;
327	                        SetProperDataPart(dst_ptr, dst_base, GetProperDataPart(src_ptr, src_offset));
328	                    }
329	                }
330	            }
331	        }
332	    }
333	}
334	
335	template <typename DstTileData, typename SrcTileData>
336	void TTrans_Impl(DstTileData& dst, SrcTileData& src)
337	{
338	    unsigned validRow = src.GetValidRow();
339	    unsigned validCol = src.GetValidCol();
340	    for (size_t c = 0; c < validCol; c++) {
341	        for (size_t r = 0; r < validRow; r++) {
342	            dst.SetElement(c, r, src.GetElement(r, c));
343	        }
344	    }
345	}
346	
347	template <typename DstTileData, typename SrcTileData>
348	PTO_INTERNAL void TTRANS_CONV_IMPL(DstTileData& dst, SrcTileData& src)
349	{
350	    CheckValidConvShape<DstTileData, SrcTileData>(dst, src);
351	    constexpr Layout src_layout = SrcTileData::layout;
352	    constexpr Layout dst_layout = DstTileData::layout;
353	
354	    if constexpr (src_layout == Layout::NCHW && dst_layout == Layout::NC1HWC0) {
355	        TTRANS_NCHW2NC1HWC0(dst, src);
356	    } else if constexpr (src_layout == Layout::NC1HWC0 && dst_layout == Layout::NCHW) {
357	        TTRANS_NC1HWC02NCHW(dst, src);
358	    } else if constexpr (src_layout == Layout::NC1HWC0 && dst_layout == Layout::FRACTAL_Z) {
359	        TTRANS_NC1HWC02C1HWN1N0C0(dst, src);
360	    } else if constexpr (src_layout == Layout::GNCHW && dst_layout == Layout::GNC1HWC0) {
361	        TTRANS_GNCHW2NC1HWC0(dst, src);
362	    } else if constexpr (src_layout == Layout::GNC1HWC0 && dst_layout == Layout::FRACTAL_Z) {
363	        TTRANS_GNC1HWC02C1HWN1N0C0(dst, src);
364	    } else if constexpr (src_layout == Layout::NCDHW && dst_layout == Layout::FRACTAL_Z_3D) {
365	        TTRANS_NCDHW2DC1HWN1N0C0(dst, src);
366	    }
367	}
368	
369	template <typename DstTileData, typename SrcTileData, typename TmpTileData>
370	PTO_INTERNAL void TTRANS_IMPL(DstTileData& dst, SrcTileData& src, TmpTileData& tmp)
371	{
372	    // Validate matching element widths at compilation
373	    static_assert(
374	        sizeof(typename SrcTileData::DType) == sizeof(typename DstTileData::DType),
375	        "Data type sizes between source and destination tiles must match.");
376	
377	    if constexpr (is_conv_tile_v<SrcTileData> && is_conv_tile_v<DstTileData>) {
378	        TTRANS_CONV_IMPL(dst, src);
379	    } else if constexpr (is_tile_data_v<SrcTileData> && is_tile_data_v<DstTileData>) {
380	        static_assert(
381	            SrcTileData::ValidRow == DstTileData::ValidCol && SrcTileData::ValidCol == DstTileData::ValidRow,
382	            "Hardware matrix tiles transpose dimension sizes must mirror match.");
383	        TTrans_Impl<DstTileData, SrcTileData>(dst, src);
384	    }
385	}
386	
387	} // namespace pto
388	
389	#endif // TTRANS_HPP
