37	    TASSIGN(dstTile, aligned_Cols * aligned_Rows * sizeof(typename TileDataSrc::DType));
38	    TASSIGN(tmpTile, 2 * aligned_Cols * aligned_Rows * sizeof(typename TileDataSrc::DType));
