42	    GlobalData srcGlobal(src + offset, pto::Shape(1, 1, 1, kGRows_, kGCols_), pto::Stride(1, 1, 1, kGCols_, 1));
43	
44	    GlobalData dstGlobal(out + offset, pto::Shape(1, 1, 1, kGCols_, kGRows_), pto::Stride(1, 1, 1, kGRows_, 1));
45	
46	    TLOAD(srcTile, srcGlobal);
47	
48	    set_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
49	    wait_flag(PIPE_MTE2, PIPE_V, EVENT_ID0);
50	
51	    TTRANS(dstTile, srcTile, tmpTile);
52	
53	    set_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
54	    wait_flag(PIPE_V, PIPE_MTE3, EVENT_ID0);
55	
56	    TSTORE(dstGlobal, dstTile);
57	
58	    out = dstGlobal.data();
